<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue';
import * as THREE from 'three';
import { createCelestial,disposeScene } from '../celestial3d.js';
import { assetUrl } from '../assets.js';
const emit=defineEmits(['playing']);const host=ref(null),failed=ref(false),phase=ref('在地球上，开始一次仰望。');
const running=ref(!matchMedia('(prefers-reduced-motion: reduce)').matches);let renderer,camera,ground,space,moon,earth,clock,frame,observer,elapsed=0,recorder;
const vec=(x,y,z)=>new THREE.Vector3(x,y,z),ease=t=>t*t*(3-2*t);
function sphere(radius,color){return new THREE.Mesh(new THREE.SphereGeometry(radius,28,20),new THREE.MeshStandardMaterial({color,roughness:.8}))}
function cylinder(radius,length,color){return new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,length,48),new THREE.MeshStandardMaterial({color,metalness:.45,roughness:.35}))}
function stars(scene){const points=[];let seed=34892;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<2300;i++){const theta=rand()*Math.PI*2,phi=Math.acos(2*rand()-1),r=70+rand()*80;points.push(Math.sin(phi)*Math.cos(theta)*r,Math.cos(phi)*r,Math.sin(phi)*Math.sin(theta)*r)}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(points,3));scene.add(new THREE.Points(geo,new THREE.PointsMaterial({color:0xd8eaff,size:.15,sizeAttenuation:true})))}
function createGround(){const s=new THREE.Scene();s.background=new THREE.Color('#030c1e');s.fog=new THREE.FogExp2('#091526',.012);stars(s);s.add(new THREE.HemisphereLight(0x809ac5,0x182919,1.5));const light=new THREE.DirectionalLight(0x9bbfff,2);light.position.set(4,8,3);s.add(light);const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:0x152825,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.05;s.add(floor);for(let i=0;i<35;i++){const mountain=new THREE.Mesh(new THREE.ConeGeometry(5+Math.sin(i*8)*2,5+Math.cos(i*5)*2,5),new THREE.MeshStandardMaterial({color:0x102024,flatShading:true}));const a=i/35*Math.PI*2;mountain.position.set(Math.cos(a)*36,1.5,Math.sin(a)*36);s.add(mountain)}
 const scope=new THREE.Group();const tube=cylinder(.28,2.8,0xe1d9cb);tube.rotation.x=.95;tube.position.y=2;s.add(scope);scope.add(tube);const lens=new THREE.Mesh(new THREE.CylinderGeometry(.252,.252,.04,48),new THREE.MeshStandardMaterial({color:0x376c83,metalness:.85,roughness:.12}));lens.rotation.x=.95;lens.position.set(0,2+Math.cos(.95)*1.42,-Math.sin(.95)*1.42);scope.add(lens);const eye=cylinder(.12,.42,0x263240);eye.rotation.x=.95;eye.position.set(0,2-Math.cos(.95)*1.55,Math.sin(.95)*1.55);scope.add(eye);const stand=cylinder(.06,1.6,0x6e7a80);stand.position.y=.95;scope.add(stand);for(let i=0;i<3;i++){const leg=cylinder(.045,1.5,0x829195);leg.rotation.z=.55;const g=new THREE.Group();g.rotation.y=i*Math.PI*2/3;leg.position.set(.4,.65,0);g.add(leg);scope.add(g)}
 const person=new THREE.Group();const torso=cylinder(.28,.7,0x996f50);torso.position.y=1.1;person.add(torso);const head=sphere(.22,0xd2ac8f);head.position.set(0,1.67,-.15);person.add(head);for(const x of [-.14,.14]){const leg=cylinder(.09,.8,0x283549);leg.position.set(x,.4,.05);person.add(leg)}const arm=cylinder(.08,.65,0x996f50);arm.rotation.x=.7;arm.position.set(.3,1.35,-.25);person.add(arm);person.position.set(.15,0,1.75);person.rotation.x=-.08;s.add(person);const distantMoon=createCelestial('moon');distantMoon.scale.setScalar(1.8);distantMoon.position.set(2,26,-35);s.add(distantMoon);return s}
function createSpace(){const s=new THREE.Scene();s.background=new THREE.Color('#020713');stars(s);s.add(new THREE.AmbientLight(0x65779a,.8));const sun=new THREE.DirectionalLight(0xfff0d5,4);sun.position.set(-15,10,20);s.add(sun);moon=createCelestial('moon');moon.scale.setScalar(3);s.add(moon);earth=createCelestial('earth');earth.scale.setScalar(5);earth.position.set(-13,-4,20);s.add(earth);return s}
function render(){const t=elapsed%38;let scene;if(t<10||t>=34){scene=ground;const q=t<10?ease(Math.min(t/8,1)):1-ease((t-34)/4);camera.position.copy(vec(5,2.8,6).lerp(vec(0,1.27,1.62),q));camera.lookAt(vec(0,2.3,-.4).lerp(vec(0,3.2,-1.3),q));phase.value=t<8?'01 / 地球 · 一位爱好者的观星之夜':t<10?'02 / 穿过目镜，靠近月亮':'05 / 返回地球，好奇仍在继续。'}else{scene=space;if(t<16){const q=ease((t-10)/6);camera.position.copy(vec(0,2,42).lerp(vec(0,2,9),q));camera.lookAt(0,0,0);phase.value='02 / 从望远镜出发，飞向月球。'}else if(t<28){const a=(t-16)/12*Math.PI*2;camera.position.set(Math.sin(a)*9,2+Math.sin(a)*.5,Math.cos(a)*9);camera.lookAt(0,0,0);phase.value='03 / 环绕月球一周，看看另一面。'}else{const q=ease((t-28)/6);camera.position.copy(vec(0,2,9).lerp(vec(-13,0,36),q));camera.lookAt(vec(0,0,0).lerp(earth.position,q));phase.value='04 / 让目光，重新回到蓝色家园。'}earth.rotation.y=t*.018}renderer.render(scene,camera)}
function tick(){frame=requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.1);if(running.value)elapsed+=dt;render()}
async function play(){running.value=true;emit('playing',true)}function pause(){running.value=false;emit('playing',false)}async function fullScreen(){await host.value?.requestFullscreen?.()}
async function recordFilm(){if(!renderer)throw new Error('三维渲染器不可用');const type=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));const stream=renderer.domElement.captureStream(30);const chunks=[];recorder=new MediaRecorder(stream,{mimeType:type,videoBitsPerSecond:7000000});elapsed=0;running.value=true;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};const finished=new Promise(resolve=>{recorder.onstop=()=>resolve(new Blob(chunks,{type}))});recorder.start();await new Promise(resolve=>setTimeout(resolve,38000));recorder.stop();const blob=await finished;stream.getTracks().forEach(t=>t.stop());const url=URL.createObjectURL(blob);return {size:blob.size,url}}
defineExpose({play,pause,fullScreen,recordFilm});
onMounted(()=>{try{renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));host.value.appendChild(renderer.domElement);camera=new THREE.PerspectiveCamera(48,1,.05,400);ground=createGround();space=createSpace();clock=new THREE.Clock();observer=new ResizeObserver(()=>{const w=host.value.clientWidth,h=host.value.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()});observer.observe(host.value);tick();emit('playing',running.value)}catch{failed.value=true}});
onBeforeUnmount(()=>{cancelAnimationFrame(frame);observer?.disconnect();if(ground)disposeScene(ground);if(space)disposeScene(space);renderer?.dispose();recorder?.state==='recording'&&recorder.stop()});
</script>
<template><div class="observatory-journey" ref="host"><img v-if="failed" :src="assetUrl('/images/moon-tour-poster.jpg')" alt="月球表面"/><span class="journey-phase">{{phase}}</span><small class="journey-science">原创三维镜头 · 距离和飞行过程为艺术示意</small></div></template>

